using System;using System.Configuration;using System.Web;using System.Web.UI;namespace ZavaAccountManager{public partial class Login:Page{protected void Page_Load(object sender,EventArgs e){var ret=(Request.QueryString["ReturnUrl"]??"~/Default.aspx").Trim();if(Request.IsAuthenticated){Response.Redirect(ResolveClientUrl(ret),false);Context.ApplicationInstance.CompleteRequest();return;}lnkAuthGateway.NavigateUrl=(ConfigurationManager.AppSettings["AuthGatewayLoginUrl"]??"http://localhost:8000/Login.aspx")+"?ReturnUrl="+HttpUtility.UrlEncode(ResolveClientUrl(ret));lblMessage.Text="Admin and teller users authenticate via ZavaAuthGateway.";}}}
